using System;
using System.DirectoryServices;
using System.Security.Cryptography;
using System.Text;
using System.Collections.Generic;
using System.Linq;

namespace PaymentGateway.Auth
{
    public class LdapRoleProvider
    {
        private readonly string _ldapPath;
        private readonly string _serviceAccount;
        private readonly string _servicePassword;

        public LdapRoleProvider(string ldapPath, string serviceAccount, string servicePassword)
        {
            _ldapPath = ldapPath;
            _serviceAccount = serviceAccount;
            _servicePassword = servicePassword;
        }

        public string SanitizeLdapInput(string input)
        {
            if (string.IsNullOrEmpty(input)) return input;

            var sb = new StringBuilder();
            foreach (char c in input)
            {
                switch (c)
                {
                    case '\\':
                        sb.Append("\\5c");
                        break;
                    case '*':
                        sb.Append("\\2a");
                        break;
                    case '(':
                        sb.Append("\\28");
                        break;
                    case ')':
                        sb.Append("\\29");
                        break;
                    case '\0':
                        sb.Append("\\00");
                        break;
                    default:
                        sb.Append(c);
                        break;
                }
            }
            return sb.ToString();
        }

        public string NormalizeDN(string distinguishedName)
        {
            if (string.IsNullOrEmpty(distinguishedName)) return distinguishedName;
            // Normalize DN components for consistent lookup
            var parts = distinguishedName.Split(',');
            var normalized = parts.Select(p => p.Trim()).ToArray();
            return string.Join(",", normalized);
        }

        public List<string> GetUserRoles(string username)
        {
            string sanitizedUser = SanitizeLdapInput(username);
            string filter = $"(&(objectClass=user)(sAMAccountName={sanitizedUser}))";
            return ExecuteLdapQuery(filter, "memberOf");
        }

        public PaymentAuthResult AuthorizePayment(string username, string merchantId, decimal amount)
        {
            var roles = GetUserRoles(username);
            var merchantDN = ResolveMerchantDN(merchantId);

            if (merchantDN == null)
                return new PaymentAuthResult { Authorized = false, Reason = "Merchant not found" };

            var limits = GetTransactionLimits(username, merchantDN);

            if (amount > limits.MaxAmount)
                return new PaymentAuthResult { Authorized = false, Reason = "Exceeds limit" };

            bool hasRole = roles.Any(r => r.Contains("CN=PaymentProcessors") || r.Contains("CN=Admins"));
            return new PaymentAuthResult { Authorized = hasRole, Reason = hasRole ? "OK" : "Insufficient role" };
        }

        private string ResolveMerchantDN(string merchantId)
        {
            string sanitizedId = SanitizeLdapInput(merchantId);
            string filter = $"(&(objectClass=organizationalUnit)(ou={sanitizedId}))";
            var results = ExecuteLdapQuery(filter, "distinguishedName");
            return results.FirstOrDefault();
        }

        public TransactionLimits GetTransactionLimits(string username, string merchantDN)
        {
            // Lookup is by normalized DN - no user input in filter directly
            string normalizedDN = NormalizeDN(merchantDN);
            string filter = BuildLimitFilter(username, normalizedDN);
            var results = ExecuteLdapQuery(filter, "transactionLimit");

            decimal maxAmount = 1000.00m; // default
            if (results.Any())
            {
                decimal.TryParse(results.First(), out maxAmount);
            }
            return new TransactionLimits { MaxAmount = maxAmount };
        }

        private string BuildLimitFilter(string username, string merchantContext)
        {
            // Username already sanitized in calling path for role lookup,
            // but merchantContext comes from LDAP result (trusted DN)
            string sanitizedUser = SanitizeLdapInput(username);
            string sanitizedContext = SanitizeLdapInput(merchantContext);
            return $"(&(objectClass=transactionPolicy)(member={sanitizedUser})(ou={sanitizedContext}))";
        }

        public bool UpdateMerchantLimit(string adminUser, string merchantId, string newLimit)
        {
            var roles = GetUserRoles(adminUser);
            if (!roles.Any(r => r.Contains("CN=Admins")))
                return false;

            string merchantDN = ResolveMerchantDN(merchantId);
            if (merchantDN == null) return false;

            // Admin operation: update limit attribute
            string filter = BuildAdminFilter(merchantDN, newLimit);
            var results = ExecuteLdapQuery(filter, "dn");
            return results.Any();
        }

        private string BuildAdminFilter(string merchantDN, string limitValue)
        {
            // merchantDN from directory lookup (trusted)
            // limitValue must be sanitized even though it should be numeric
            string sanitizedDN = SanitizeLdapInput(merchantDN);
            string sanitizedLimit = SanitizeLdapInput(limitValue);
            return $"(&(objectClass=transactionPolicy)(ou={sanitizedDN})(transactionLimit={sanitizedLimit}))";
        }

        private List<string> ExecuteLdapQuery(string filter, string attribute)
        {
            var results = new List<string>();
            try
            {
                using (var entry = new DirectoryEntry(_ldapPath, _serviceAccount, _servicePassword))
                using (var searcher = new DirectorySearcher(entry))
                {
                    searcher.Filter = filter;
                    searcher.PropertiesToLoad.Add(attribute);

                    foreach (SearchResult result in searcher.FindAll())
                    {
                        if (result.Properties.Contains(attribute))
                        {
                            foreach (var val in result.Properties[attribute])
                                results.Add(val.ToString());
                        }
                    }
                }
            }
            catch (Exception)
            {
                // Log and return empty
            }
            return results;
        }
    }

    public class PaymentAuthResult
    {
        public bool Authorized { get; set; }
        public string Reason { get; set; }
    }

    public class TransactionLimits
    {
        public decimal MaxAmount { get; set; }
    }
}
